// Cache-Aside Pattern in Node.js with Redis
async function getCachedUser(userId) {
  const cached = await redis.get(`user:${userId}`);
  if (cached) return JSON.parse(cached);

  const user = await db.findUser(userId);
  await redis.setex(`user:${userId}`, 3600, JSON.stringify(user));
  return user;
}

// Kafka Consumer in Node.js (kafkajs)
const { Kafka } = require('kafkajs');
const kafka = new Kafka({ brokers: ['localhost:9092'] });
const consumer = kafka.consumer({ groupId: 'order-service' });

await consumer.connect();
await consumer.subscribe({ topic: 'order-events' });
await consumer.run({
  eachMessage: async ({ message }) => {
    console.log(`Order Processed: ${message.value.toString()}`);
  }
});

// Prometheus Custom Counter in Express
const client = require('prom-client');
const httpRequestCounter = new client.Counter({
  name: 'http_requests_total',
  help: 'Total HTTP requests count',
  labelNames: ['method', 'status']
});

app.use((req, res, next) => {
  res.on('finish', () => {
    httpRequestCounter.inc({ method: req.method, status: res.statusCode });
  });
  next();
});

